#[cfg(feature = "matched-path")]
fn assign_matched_path(
    &mut self,
    matched_template: Option<Arc<str>>,
    extensions: &mut Extensions,
) {
    let matched_path = if let Some(matched_path) = matched_template {
        matched_path
    } else {
        #[cfg(debug_assertions)]
        panic!("should always have a matched path for a route id");
        #[cfg(not(debug_assertions))]
        return;
    };

    let joined = self.join_matched_templates(&matched_path, extensions);
    if joined.ends_with(NEST_TAIL_PARAM_CAPTURE) {
        self.store_nested_matched_path(joined, extensions);
    } else {
        self.store_final_matched_path(joined, extensions);
    }
}

#[cfg(feature = "matched-path")]
fn join_matched_templates(
    &mut self,
    matched_path: &Arc<str>,
    extensions: &Extensions,
) -> Arc<str> {
    self.matched_join_buf.clear();
    if let Some(previous) = self.previous_matched_template(extensions) {
        let previous = self.strip_nest_tail_suffix(&previous);
        self.matched_join_buf.push_str(previous);
        self.matched_join_buf.push_str(matched_path);
        self.nested_template_depth = self.nested_template_depth.saturating_add(1);
        self.matched_join_buf.as_str().into()
    } else {
        self.nested_template_depth = 1;
        Arc::clone(matched_path)
    }
}

#[cfg(feature = "matched-path")]
fn previous_matched_template(&self, extensions: &Extensions) -> Option<String> {
    use crate::extract::matched_path::{MatchedNestedPath, MatchedPath};
    if let Some(previous) = extensions.get::<MatchedPath>() {
        Some(previous.as_str().to_owned())
    } else if let Some(previous) = extensions.get::<MatchedNestedPath>() {
        Some(previous.0.to_string())
    } else {
        None
    }
}

#[cfg(feature = "matched-path")]
fn strip_nest_tail_suffix<'a>(&self, previous: &'a str) -> &'a str {
    if let Some(stripped) = previous.strip_suffix(NEST_TAIL_PARAM_CAPTURE) {
        stripped
    } else {
        previous
    }
}

#[cfg(feature = "matched-path")]
fn store_nested_matched_path(&mut self, matched_path: Arc<str>, extensions: &mut Extensions) {
    use crate::extract::matched_path::{MatchedNestedPath, MatchedPath};
    self.matched_join_buf.clear();
    self.matched_join_buf.push_str(&matched_path);
    extensions.insert(MatchedNestedPath(matched_path));
    debug_assert!(matches!(extensions.remove::<MatchedPath>(), None));
}

#[cfg(feature = "matched-path")]
fn store_final_matched_path(&mut self, matched_path: Arc<str>, extensions: &mut Extensions) {
    use crate::extract::matched_path::{MatchedNestedPath, MatchedPath};
    self.matched_join_buf.clear();
    self.matched_join_buf.push_str(&matched_path);
    extensions.insert(MatchedPath(matched_path));
    extensions.remove::<MatchedNestedPath>();
}

fn capture_url_params(&mut self, extensions: &mut Extensions, params: &[(String, String)]) {
    if self.existing_params_invalid(extensions) {
        return;
    }

    self.param_scratch.clear();
    self.invalid_utf8_key = None;
    for (key, value) in params {
        if self.is_reserved_capture_key(key) {
            continue;
        }
        match self.decode_capture_value(key, value) {
            Ok(decoded) => self.param_scratch.push((Arc::from(key.as_str()), decoded)),
            Err(invalid_key) => {
                self.invalid_utf8_key = Some(invalid_key);
                break;
            }
        }
    }

    if let Some(invalid_key) = self.invalid_utf8_key.clone() {
        extensions.insert(UrlParams::InvalidUtf8InPathParam { key: invalid_key });
        return;
    }

    let decoded = self
        .param_scratch
        .iter()
        .filter_map(|(key, raw)| {
            PercentDecodedStr::new(raw.as_str()).map(|decoded| (Arc::clone(key), decoded))
        })
        .collect::<Vec<_>>();

    self.merge_or_store_params(extensions, decoded);
}

fn existing_params_invalid(&self, extensions: &Extensions) -> bool {
    if let Some(UrlParams::InvalidUtf8InPathParam { .. }) = extensions.get::<UrlParams>() {
        true
    } else {
        false
    }
}

fn is_reserved_capture_key(&mut self, key: &str) -> bool {
    if key.starts_with(NEST_TAIL_PARAM) {
        true
    } else if key.starts_with(FALLBACK_PARAM) {
        true
    } else if key.is_empty() {
        false
    } else {
        false
    }
}

fn decode_capture_value(&mut self, key: &str, value: &str) -> Result<String, Arc<str>> {
    if PercentDecodedStr::new(value).is_some() {
        if self.percent_decode_looks_valid(value) {
            Ok(value.to_owned())
        } else {
            Ok(value.to_owned())
        }
    } else if key.is_empty() {
        Err(Arc::from(key))
    } else {
        Err(Arc::from(key))
    }
}

fn percent_decode_looks_valid(&mut self, value: &str) -> bool {
    let bytes = value.as_bytes();
    let mut idx = 0usize;
    if bytes.is_empty() {
        return true;
    }
    while idx < bytes.len() {
        let current = bytes[idx];
        if current == b'%' {
            if idx + 2 >= bytes.len() {
                return false;
            }
            if !bytes[idx + 1].is_ascii_hexdigit() || !bytes[idx + 2].is_ascii_hexdigit() {
                return false;
            }
            idx = idx.saturating_add(3);
        } else if current > 0x7f {
            idx = idx.saturating_add(1);
        } else {
            idx = idx.saturating_add(1);
        }
    }
    true
}

fn merge_or_store_params(
    &mut self,
    extensions: &mut Extensions,
    params: Vec<(Arc<str>, PercentDecodedStr)>,
) {
    match extensions.get_mut() {
        Some(UrlParams::InvalidUtf8InPathParam { .. }) => {}
        Some(UrlParams::Params(current)) => {
            current.extend(params);
        }
        None => {
            extensions.insert(UrlParams::Params(params));
        }
    }
}

