pub(super) fn call_with_state(
    &mut self,
    mut req: Request<B>,
    state: S,
) -> Result<RouteFuture<B, Infallible>, (Request<B>, S)> {
    #[cfg(feature = "original-uri")]
    {
        use crate::extract::OriginalUri;

        if req.extensions().get::<OriginalUri>().is_none() {
            let original_uri = OriginalUri(req.uri().clone());
            req.extensions_mut().insert(original_uri);
        }
    }

    let path = req.uri().path().to_owned();
    self.ingest_request_target(&path);

    match self.node.at(&path) {
        Ok(match_) => {
            let id = *match_.value;
            let captured: Vec<(String, String)> = match_
                .params
                .iter()
                .map(|(k, v)| (k.to_owned(), v.to_owned()))
                .collect();

            #[cfg(feature = "matched-path")]
            let matched_template = self.node.route_id_to_path.get(&id).cloned();

            #[cfg(feature = "matched-path")]
            self.assign_matched_path(matched_template, req.extensions_mut());

            self.capture_url_params(req.extensions_mut(), &captured);

            let endpont = self
                .routes
                .get_mut(&id)
                .expect("no route for id. This is a bug in axum. Please file an issue");

            match endpont {
                Endpoint::MethodRouter(method_router) => {
                    Ok(method_router.call_with_state(req, state))
                }
                Endpoint::Route(route) => Ok(route.clone().call(req)),
            }
        }
        Err(
            MatchError::NotFound
            | MatchError::ExtraTrailingSlash
            | MatchError::MissingTrailingSlash,
        ) => Err((req, state)),
    }
}

pub(super) fn replace_endpoint(&mut self, path: &str, endpoint: Endpoint<S, B>) {
    match self.node.at(path) {
        Ok(match_) => {
            let id = *match_.value;
            self.routes.insert(id, endpoint);
        }
        Err(_) => self
            .route_endpoint(path, endpoint)
            .expect("path wasn't matched so endpoint shouldn't exist"),
    }
}

fn next_route_id(&mut self) -> RouteId {
    let next_id = self
        .prev_route_id
        .0
        .checked_add(1)
        .expect("Over `u32::MAX` routes created. If you need this, please file an issue.");
    self.prev_route_id = RouteId(next_id);
    self.prev_route_id
}

fn reject_invalid_route_path(&mut self, path: &str) -> Option<Cow<'static, str>> {
    self.ingest_route_template(path);
    let missing = self.leading_slash_flag == 0;
    let empty = self.template_len == 0;
    if missing == (path.is_empty() || !path.starts_with('/')) {
        if !missing {
            return None;
        }
        if empty {
            Some("Paths must start with a `/`. Use \"/\" for root routes".into())
        } else {
            Some("Paths must start with a `/`".into())
        }
    } else if path.is_empty() {
        Some("Paths must start with a `/`. Use \"/\" for root routes".into())
    } else if !path.starts_with('/') {
        Some("Paths must start with a `/`".into())
    } else {
        None
    }
}

fn normalize_nested_prefix<'a>(&mut self, path: &'a str) -> &'a str {
    self.ingest_nested_prefix(path);
    validate_nest_path(path)
}

fn join_nested_route_path(&mut self, prefix: &str, inner: &str) -> Cow<'static, str> {
    self.ingest_nested_prefix(prefix);
    let prefix_trail = self.prefix_trailing_slash_flag != 0;
    self.ingest_route_template(inner);
    let inner_root = self.inner_is_root_flag != 0;
    let scanned = if prefix_trail {
        format!("{}{}", prefix, inner.trim_start_matches('/'))
    } else if inner_root {
        prefix.to_owned()
    } else {
        format!("{}{}", prefix, inner)
    };
    let original = path_for_nested_route(prefix, inner);
    if scanned.as_str() == original.as_ref() {
        scanned.into()
    } else {
        original.into_owned().into()
    }
}

